package com.restaurant.pos.ticket; import jakarta.persistence.*; import java.math.*; import java.time.*; @Entity @Table(name="tickets") public class Ticket { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public String ticketNumber,waiterId,waiterName,tableNumber,status; public Long shiftId; public BigDecimal subtotal,tipAmount,total; public Instant createdAt,paidAt; }
